schema.sdl:
# Schema shape for the Pokédex fixture API.
#
# Independent reimplementation written for interoperability testing: type,
# field and argument names (and their nullability) follow the shape documented
# in research/pokedex-example-spec.md section D, because that shape is the
# interface Houdini's documents need. No schema source was copied.
scalar Map

type Query {
	pokemon(first: Int, after: String): SpeciesConnection!
	species(id: Int!, delay: Int): Species
	favorites: [Species!]!
}

type Species {
	id: Int!
	pokedexNumber: Int!
	name: String!
	flavor_text: String!
	base_stats: Map!
	favorite: Boolean!
	evolution_chain: [Species!]!
	moves(first: Int, after: String, last: Int, before: String): SpeciesMoveConnection!
	types: [Type!]!
	sprites: SpeciesSprites!
}

type SpeciesSprites {
	front: String!
	back: String!
}

type SpeciesMove {
	learned_at: Int!
	method: String!
	move: Move!
}

type Move {
	name: String!
	power: Int
	accuracy: Int
	pp: Int!
	type: Type
}

enum Type {
	Grass
	Poison
	Fire
	Flying
	Water
	Bug
	Normal
	Electric
	Ground
	Fairy
	Fighting
	Psychic
	Rock
	Steel
	Ice
	Ghost
	Dragon
	Dark
}

type SpeciesConnection {
	edges: [SpeciesEdge!]!
	pageInfo: PageInfo!
	totalCount: Int!
}

type SpeciesEdge {
	cursor: String
	node: Species
}

type SpeciesMoveConnection {
	edges: [SpeciesMoveEdge!]!
	pageInfo: PageInfo!
	totalCount: Int!
}

type SpeciesMoveEdge {
	cursor: String
	node: SpeciesMove
}

type PageInfo {
	endCursor: String
	hasNextPage: Boolean!
	hasPreviousPage: Boolean!
	startCursor: String
}

type Mutation {
	toggleFavorite(id: Int!): ToggleFavoriteOutput
}

type ToggleFavoriteOutput {
	species: Species
}

type Subscription {
	speciesFavoriteToggled: SpeciesFavoriteToggledOutput!
}

type SpeciesFavoriteToggledOutput {
	species: Species!
}

inputs.text:
import { graphql } from '$flamme'

export const ToggleFavorite = graphql`mutation ToggleFavorite($id: Int!) {
	toggleFavorite(id: $id) {
		species {
			id
			favorite
			...FavoriteSpecies_toggle
		}
	}
}
`

query Info($id: Int! = 1) @loading {
	species(id: $id, delay: 500) {
		id
		pokedexNumber
		name
		flavor_text
		favorite
		...SpriteInfo
		evolution_chain {
			id
			...SpeciesPreview
		}
		moves(first: 1) @paginate(mode: SinglePage, name: "Species_Moves") {
			edges @loading(count: 1) {
				node {
					...MoveDisplay @mask_enable
				}
			}
			pageInfo {
				hasNextPage
				hasPreviousPage
			}
		}
	}
}

